import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s1-u09")

L(1, "O que tens na mala?", "Objetos que levamos connosco.",
  ["Nomear objetos pessoais com o artigo certo"],
  vocab=[V("v-sleutel","sleutel","chave","noun","de","sleutels"), V("v-telefoon","telefoon","telefone|telemóvel","noun","de","telefoons",note="Para telemóvel também se diz «mobiel»."),
         V("v-tas","tas","mala|saco","noun","de","tassen"), V("v-portemonnee","portemonnee","carteira","noun","de"),
         V("v-bril","bril","óculos","noun","de","brillen",note="Singular em neerlandês: de bril = os óculos."),
         V("v-paspoort","paspoort","passaporte","noun","het","paspoorten")],
  ex=[("Ik heb mijn sleutel en mijn telefoon.","Tenho a minha chave e o meu telemóvel."),("Waar is mijn bril?","Onde estão os meus óculos?","Singular em neerlandês!"),("Mijn paspoort zit in mijn tas.","O meu passaporte está na minha mala.")],
  gram=[G("g-bril-singular","Óculos no singular","Algumas palavras que em português são plurais são **singulares** em neerlandês: **de bril** (os óculos), **de broek** (as calças), **de schaar** (a tesoura). Por isso: *mijn bril **is** weg* (os meus óculos desapareceram).",
    [("Mijn bril is nieuw.","Os meus óculos são novos.")])],
  review=["v-hebben","v-mijn","v-waar"],
  exs=[
    MA([("sleutel","chave"),("tas","mala"),("bril","óculos"),("paspoort","passaporte"),("portemonnee","carteira")], "Objetos pessoais.", ["v-sleutel","v-tas","v-bril","v-paspoort","v-portemonnee"]),
    AR("paspoort","o passaporte","het", "«Het paspoort».", ["v-paspoort"]),
    AR("sleutel","a chave","de", "«De sleutel».", ["v-sleutel"]),
    MC("Como se diz «Onde estão os meus óculos?»", ["*Waar is mijn bril?","Waar zijn mijn brillen?|«brillen» seriam vários pares de óculos.","Waar is mijn brillen?|Singular: bril."], "de bril é singular: waar is mijn bril?", ["v-bril"]),
    TR("pt-nl","Onde está a minha chave?", ["Waar is mijn sleutel"], "Waar + is + sujeito.", ["v-sleutel","v-waar"], bank=["Waar","is","mijn","sleutel?","zijn","tas"]),
    TR("nl-pt","Ik heb mijn telefoon niet.", ["Não tenho o (meu )telemóvel","Não tenho o (meu )telefone"], "«niet» no fim nega a frase.", ["v-telefoon","v-niet"]),
    FB("Mijn paspoort zit in mijn ___.", ["tas"], "«zitten in» = estar dentro de.", ["v-tas","v-paspoort"], choices=["tas","bril","sleutel"], tr="O meu passaporte está na minha mala."),
    LI("Waar is mijn portemonnee?", ["Waar is mijn portemonnee"], "Onde está a minha carteira?", "Palavra de origem francesa: «port-mo-NÊ».", ["v-portemonnee"]),
    FE(["Mijn","bril","zijn","nieuw."], 2, "is", "«de bril» é singular: is.", ["v-bril"]),
    DL([("Eva","Heb je alles? Sleutel, telefoon?","Tens tudo? Chave, telemóvel?"),("Tom","")], ["*Ja, en mijn portemonnee ook.","Ja, ik ben mijn sleutel.|Usa-se «hebben», não «zijn».","Nee, ik heb geen honger.|Isso é «não tenho fome»."], "«ook» no fim = também.", ["v-portemonnee","v-ook"]),
  ], diff=1, mins=5)

L(2, "À mesa", "Mesa, prato, copo e talheres.",
  ["Nomear objetos da mesa e da cozinha"],
  vocab=[V("v-tafel","tafel","mesa","noun","de","tafels"), V("v-bord","bord","prato","noun","het","borden"),
         V("v-glas","glas","copo|vidro","noun","het","glazen"), V("v-mes","mes","faca","noun","het","messen"),
         V("v-vork","vork","garfo","noun","de","vorken"), V("v-lepel","lepel","colher","noun","de","lepels")],
  ex=[("Een glas water, alstublieft.","Um copo de água, por favor."),("Het mes en de vork liggen op tafel.","A faca e o garfo estão em cima da mesa."),("Mag ik een lepel?","Pode dar-me uma colher?")],
  gram=[G("g-mag-ik","Mag ik…?","Para pedir algo com educação: **Mag ik een glas water?** (posso ter / pode dar-me um copo de água?). É muito usado em lojas e restaurantes.",
    [("Mag ik een vork?","Pode dar-me um garfo?")],
    "Em português dizemos «pode dar-me…?»; em neerlandês é comum «posso (ter)…?».")],
  review=["v-water","v-koffie","v-kop","v-alstublieft"],
  exs=[
    MA([("tafel","mesa"),("bord","prato"),("glas","copo"),("vork","garfo"),("lepel","colher")], "À mesa.", ["v-tafel","v-bord","v-glas","v-vork","v-lepel"]),
    AR("mes","a faca","het", "«Het mes» — plural «messen».", ["v-mes"]),
    AR("vork","o garfo","de", "«De vork».", ["v-vork"]),
    AR("glas","o copo","het", "«Het glas» — plural «glazen» (o s passa a z).", ["v-glas"]),
    TR("pt-nl","Um copo de água, por favor.", ["Een glas water(,) [alstublieft|alsjeblieft]"], "Sem «van»: een glas water.", ["v-glas","v-water"]),
    TR("nl-pt","Mag ik een lepel?", ["Pode dar-me uma colher","Posso ter uma colher","Pode-me dar uma colher"], "Mag ik…? = pedido educado.", ["v-lepel"]),
    FE(["Een","glas","van","water,","alstublieft."], 2, "(retirar)", "Quantidade + produto sem «van»: een glas water.", ["v-glas"]),
    FB("Het bord staat op de ___.", ["tafel"], "op de tafel = em cima da mesa.", ["v-tafel","v-bord"], choices=["tafel","vork","glas"], tr="O prato está em cima da mesa."),
    LI("Het mes en de vork.", ["Het mes en de vork"], "A faca e o garfo.", "Repare nos artigos: het mes, de vork.", ["v-mes","v-vork"]),
    MC("Qual é o plural de «glas»?", ["*glazen","glasen|O «s» entre vogais passa a «z».","glassen|Vogal longa em gla-zen."], "het glas → de glazen.", ["v-glas"]),
  ], diff=1, mins=5)

L(3, "Na secretária", "Objetos de escritório e as horas no pulso.",
  ["Nomear objetos de trabalho e estudo"],
  vocab=[V("v-computer","computer","computador","noun","de","computers"), V("v-potlood","potlood","lápis","noun","het","potloden"),
         V("v-schrift","schrift","caderno","noun","het","schriften"), V("v-papier","papier","papel","noun","het"),
         V("v-klok","klok","relógio (de parede)","noun","de","klokken"), V("v-horloge","horloge","relógio (de pulso)","noun","het","horloges")],
  ex=[("Mijn computer is oud.","O meu computador é velho."),("Heb je een potlood?","Tens um lápis?"),("Het horloge is van mijn opa.","O relógio é do meu avô.")],
  gram=[G("g-van-posse","Van para posse","**van** indica de quem é algo: *het horloge is van mijn opa* (o relógio é do meu avô). *Van wie is dit?* = De quem é isto?",
    [("Van wie is de tas?","De quem é a mala?"),("De tas is van Eva.","A mala é da Eva.")])],
  review=["v-pen","v-boek","v-van","v-opa","v-oud"],
  exs=[
    MA([("computer","computador"),("potlood","lápis"),("schrift","caderno"),("papier","papel")], "Material de escritório.", ["v-computer","v-potlood","v-schrift","v-papier"]),
    MC("«het horloge» ou «de klok»: o relógio na parede da sala é…", ["*de klok","het horloge|«horloge» é o relógio de pulso."], "klok = de parede; horloge = de pulso.", ["v-klok","v-horloge"]),
    AR("potlood","o lápis","het", "«Het potlood» — plural «potloden».", ["v-potlood"]),
    AR("computer","o computador","de", "«De computer».", ["v-computer"]),
    TR("pt-nl","De quem é isto?", ["Van wie is dit"], "Van wie…? = de quem…?", ["v-van"]),
    TR("nl-pt","Het horloge is van mijn opa.", ["O relógio é do meu avô"], "van = de (posse).", ["v-horloge","v-van"]),
    FB("Heb je een ___ voor mij? Ik wil schrijven.", ["pen","potlood"], "Para escrever: pen ou potlood.", ["v-potlood"], choices=["potlood","klok","computer"], tr="Tens um lápis para mim? Quero escrever."),
    LI("Mijn computer is heel oud.", ["Mijn computer is heel oud"], "O meu computador é muito velho.", "«computer» diz-se quase como em inglês.", ["v-computer"]),
    WO("A mala é da Eva.", ["De","tas","is","van","Eva"], "van + pessoa.", ["v-tas","v-van"]),
    FE(["De","schrift","is","nieuw."], 0, "Het", "«schrift» é uma palavra het: het schrift.", ["v-schrift"]),
  ], diff=1, mins=5)

L(4, "Este, esse, aquele", "dit/dat, deze/die: os demonstrativos.",
  ["Escolher entre dit, dat, deze e die"],
  vocab=[V("v-deze","deze","este|esta|estes","determiner",note="Com palavras de e no plural."), V("v-die","die","esse|aquele|esses","determiner",note="Com palavras de e no plural."),
         V("v-dat","dat","esse|aquele|isso","determiner",note="Com palavras het no singular.")],
  ex=[("dit boek, deze tas","este livro, esta mala"),("dat huis, die stoel","aquela casa, aquela cadeira"),("deze boeken","estes livros","Plural: deze/die.")],
  gram=[G("g-demonstrativos","Demonstrativos","Perto: **dit** (palavras het) e **deze** (palavras de e plural). Longe: **dat** (het) e **die** (de e plural). *Dit boek* (het boek), *deze tas* (de tas), *deze boeken* (plural). Sozinho, para apresentar: **Dit is / Dat is…** com qualquer palavra.",
    [("Deze stoel is oud.","Esta cadeira é velha."),("Dat glas is van mij.","Esse copo é meu.")],
    "O português escolhe pelo género (este/esta); o neerlandês pelo artigo (de/het).")],
  review=["v-dit-is","v-boek","v-tas","v-huis","v-stoel","v-glas"],
  exs=[
    MC("___ boek is mooi. (este)", ["*Dit","Deze|«boek» é het: dit.","Die|«die» = aquele, para palavras de."], "het boek → dit boek.", ["v-boek"]),
    MC("___ tas is van mij. (esta)", ["*Deze","Dit|«tas» é de: deze.","Dat|«dat» = aquele, para palavras het."], "de tas → deze tas.", ["v-deze","v-tas"]),
    MC("___ huizen zijn groot. (aquelas)", ["*Die","Dat|No plural usa-se die.","Dit|«dit» = este (het, singular)."], "Plural → deze/die.", ["v-die"]),
    MA([("dit","este (het)"),("deze","este (de)"),("dat","aquele (het)"),("die","aquele (de)")], "Os quatro demonstrativos.", ["v-deze","v-die","v-dat"]),
    TR("pt-nl","Esta cadeira é velha.", ["Deze stoel is oud"], "de stoel → deze.", ["v-deze","v-stoel"], bank=["Deze","Dit","stoel","is","oud"]),
    TR("nl-pt","Dat glas is van mij.", ["Esse copo é meu","Aquele copo é meu"], "het glas → dat glas.", ["v-dat","v-glas"]),
    FE(["Dit","fiets","is","nieuw."], 0, "Deze", "de fiets → deze fiets.", ["v-deze","v-fiets"]),
    FB("Is ___ jouw sleutel? (essa)", ["die"], "de sleutel → die.", ["v-die","v-sleutel"], choices=["die","dat","dit"], tr="Essa chave é tua?"),
    LI("Deze boeken zijn van mij.", ["Deze boeken zijn van mij"], "Estes livros são meus.", "Plural: deze.", ["v-deze"]),
    TR("pt-nl","Isto é um passaporte.", ["Dit is een paspoort"], "«Dit is» para apresentar.", ["v-dit-is","v-paspoort"]),
  ], diff=2, mins=6)

L(5, "Onde está? Em cima, debaixo, ao lado", "op, onder, naast, in — e encontrar as coisas.",
  ["Dizer onde estão os objetos"],
  vocab=[V("v-op","op","em cima de|em","preposition"), V("v-onder","onder","debaixo de","preposition"),
         V("v-naast","naast","ao lado de","preposition"), V("v-achter","achter","atrás de","preposition"),
         V("v-weg","weg","desaparecido|fora","adverb",note="Mijn sleutel is weg = a minha chave desapareceu.")],
  ex=[("De sleutel ligt op de tafel.","A chave está em cima da mesa."),("De tas staat naast de stoel.","A mala está ao lado da cadeira."),("Mijn bril is weg!","Os meus óculos desapareceram!")],
  gram=[G("g-liggen-staan","Estar = liggen, staan, zitten","Para dizer onde está um objeto, o neerlandês prefere verbos de posição: **liggen** (deitado: *de sleutel ligt op tafel*), **staan** (de pé: *het glas staat op tafel*), **zitten** (dentro: *het geld zit in de tas*). **is** também se entende, mas soa menos natural.",
    [("Het boek ligt onder de stoel.","O livro está debaixo da cadeira.")],
    "O português usa «estar» para tudo; o neerlandês indica a posição.")],
  review=["v-sleutel","v-tafel","v-stoel","v-tas","v-bril","v-waar"],
  exs=[
    MA([("op","em cima de"),("onder","debaixo de"),("naast","ao lado de"),("achter","atrás de")], "Preposições de lugar.", ["v-op","v-onder","v-naast","v-achter"]),
    MC("A chave está deitada em cima da mesa. Que verbo se usa?", ["*ligt","staat|«staan» é para coisas de pé (copo, garrafa).","zit|«zitten» é para coisas dentro de algo."], "Objetos deitados: liggen.", ["v-sleutel"]),
    TR("pt-nl","A chave está em cima da mesa.", ["De sleutel ligt op [de |]tafel","De sleutel is op [de |]tafel"], "liggen op = estar (deitado) em cima de.", ["v-op","v-sleutel","v-tafel"]),
    TR("nl-pt","De tas staat naast de stoel.", ["A mala está ao lado da cadeira"], "naast = ao lado de.", ["v-naast","v-tas"]),
    FB("Het boek ligt ___ de stoel.", ["onder"], "onder = debaixo de.", ["v-onder"], choices=["onder","weg","van"], tr="O livro está debaixo da cadeira."),
    TR("nl-pt","Mijn bril is weg!", ["Os meus óculos desapareceram","Perdi os (meus )óculos","Os meus óculos sumiram"], "«weg zijn» = ter desaparecido.", ["v-weg","v-bril"]),
    WO("O cão está atrás da casa.", ["De","hond","is","achter","het","huis"], "achter = atrás de.", ["v-achter","v-hond"]),
    LI("Het geld zit in mijn tas.", ["Het geld zit in mijn tas"], "O dinheiro está na minha mala.", "zitten in = estar dentro de.", ["v-geld","v-tas"]),
    DL([("Tom","Waar is mijn telefoon?","Onde está o meu telemóvel?"),("Eva","")], ["*Hij ligt op de tafel, naast je sleutel.","Hij is mijn telefoon.|Não responde onde está.","Ja, graag!|Não faz sentido."], "Para objetos «de» usa-se «hij» como pronome: hij ligt…", ["v-op","v-naast"]),
    CO("text","A sala da Eva", "In de kamer staat een tafel. Op de tafel ligt een boek en staat een glas water. Onder de tafel ligt de hond. Naast de deur staat een oude stoel.",
       [("O que está debaixo da mesa?", ["*O cão","O livro","A cadeira"]),("Onde está a cadeira velha?", ["*Ao lado da porta","Em cima da mesa","Atrás do cão"])],
       "liggen/staan indicam a posição.", ["v-onder","v-naast","v-op"]),
  ], diff=2, mins=6)

W()
